div.script:
function copiarCupom() {
    const codigoCupom = "Bemvindo";
    navigator.clipboard.writeText(codigoCupom).then(function() {
        // Mostra a mensagem de copiado
        const mensagem = document.getElementById("mensagem-copiado");
        mensagem.style.display = 'block';
        mensagem.style.animation = 'fadeInOut 2s ease-in-out';
        setTimeout(() => {
            mensagem.style.display = 'none';
        }, 2000);
        
        // Abre o modal
        document.getElementById("modal-cupom").style.display = "block";
        
    }).catch(function(err) {
        console.error('Erro ao copiar cupom: ', err);
    });
}

function fecharModal() {
    document.getElementById("modal-cupom").style.display = "none";
}

// Fechar modal clicando fora da área de conteúdo
window.onclick = function(event) {
    const modal = document.getElementById("modal-cupom");
    if (event.target == modal) {
        modal.style.display = "none";
    }
}

body.script:
            function slugify(text) {
                return text
                    .toString()                             // Converte para string
                    .normalize('NFD')                       // Decompõe caracteres acentuados
                    .replace(/[\u0300-\u036f]/g, '')        // Remove marcas diacríticas
                    .toLowerCase()                          // Converte para minúsculas
                    .trim()                                 // Remove espaços nas extremidades
                    .replace(/[^a-z0-9\s-]/g, '')           // Remove caracteres especiais
                    .replace(/\s+/g, '-')                   // Substitui espaços por hífens
                    .replace(/-+/g, '-');                   // Remove hífens duplicados
            }
			
			
			
            (function(){
               
                if(window.cvz && window.cvz.events){
                    const urlDomain = "https://www.drogariaveracruz.com.br";
                    let dataItemEdrone;
                    

                    window.cvz.events.bind("view_item.edrone", function(data){
                        const dataItem = {
                            item_name: dataItemEdrone.sku_name,
                            sku_id: dataItemEdrone.sku,
                            product_id: dataItemEdrone.product_id,
                            price: dataItemEdrone.unit_price,
                            item_category_title: dataItemEdrone.categories ? dataItemEdrone.categories.join("~"):null,
                            item_category_id: dataItemEdrone.categories ? dataItemEdrone.categories.map(c => slugify(c)).join("~"):null,
                            item_image: dataItemEdrone.sku_image,
                            item_url: `${urlDomain}${dataItemEdrone.sku_url}`,
                            quantity: 1
                        };
                        dataLayer.push({
                            edrone_products: {
                                items: [dataItem]
                            }
                        });
                    });

                    window.cvz.events.bind("add_to_cart.edrone", function(data){
                        const dataItem = {
                            item_name: data.sku_name,
                            sku_id: data.sku,
                            product_id: data.product,
                            price: data.unit_price,
                            item_category_title: data.categories ? data.categories.join("~"):null,
                            item_category_id: data.categories ? data.categories.map(c => slugify(c)).join("~"):null,
                            item_image: data.image ? `https:${data.image}`:null,
                            item_url: `${urlDomain}${data.url}/${data.sku}/`,
                            quantity: data.quantity
                        };
                        dataLayer.push({
                            edrone_products: {
                                items: [dataItem]
                            }
                        });
                    });

                    window.cvz.events.bind("order_success.edrone", function(data){
                        if(data.first_view){
                            try {
                                dataLayer.push({
                                    edrone_products: {
                                        items: data.items.map(function(item){
                                            return{
                                                "item_name": item.description,
                                                "sku_id": item.sku,
                                                "product_id": item.product,
                                                "price": item.unit_price,
                                                "item_category_title": item.categories ? item.categories.join("~"):null,
                                                "item_category_id": item.categories ? item.categories.map(c => slugify(c)).join("~"):null,
                                                "item_image": item.image ? `https:${item.image}`:null,
                                                "item_url": `${urlDomain}${item.url}/${item.sku}/`,
                                                "quantity": item.quantity
                                            }
                                        })
                                    }
                                });
                            } catch (error) {
                                console.error(error)
                            }
                        }
                    });

                }
            })();

        (function(){
            
            

            if(window.cvz && window.cvz.events){
                window.cvz.events.bind("search.ga4", function(data){
                    dataLayer.push({
                        event: "search",
                        search_term: data.term
                    });
                });

                window.cvz.events.bind("view_cart.ga4", function(data){
                    if(data.uuid){
                        const dataEvent = {
                            event: "view_cart",
                            currency: "BRL",
                            value: data.total_payment || data.value,
                            items: data.items.map(item => ({
                                item_name: item.sku_name,
                                item_id: item.sku,
                                price: item.total_price,
                                quantity: item.quantity
                            }))
                        }
                        dataLayer.push({ items: null, value: null })
                        dataLayer.push(dataEvent)
                    } else {
                        data.event = "view_cart";
                        dataLayer.push({ items: null, value: null })
                        dataLayer.push(data)
                    }
                });

                window.cvz.events.bind("begin_checkout.ga4", function(data){
                    data.event = "begin_checkout";
                    dataLayer.push({ items: null, value: null });
                    dataLayer.push(data);
                });

                window.cvz.events.bind("view_item.ga4", function(data){
                    dataLayer.push({ items: null, value: null });
                    const dataItem = {
                        item_name: data.sku_name,
                        item_id: data.sku,
                        price: data.unit_price
                    };
                    if(data.categories) data.categories.map((c, index) => dataItem[`item_category${index+1}`] = c);
                    if(data.brand) dataItem.brand = data.brand;
                    if(data.discount) dataItem.discount = data.discount;
                    dataLayer.push({
                        event: "view_item",
                        items: [dataItem]
                    });
                });

                

                window.cvz.events.bind("add_to_cart.ga4", function(data){
                    if(!Array.isArray(data)) data = [{"item_id": data.sku, "item_name": data.sku_name, "price": data.price || data.unit_price, "quantity": data.quantity}];
                    dataLayer.push({ items: null, value: null });
                    dataLayer.push({
                        event: "add_to_cart",
                        items: data
                    });
                });

                window.cvz.events.bind("remove_from_cart.ga4", function(data){
                    if(!Array.isArray(data)) data = [{"item_id": data.sku, "item_name": data.sku_name, "quantity": data.quantity, "price": data.price || data.unit_price}];
                    dataLayer.push({ items: null, value: null });
                    dataLayer.push({
                        event: "remove_from_cart",
                        items: data
                    });
                });

                window.cvz.events.bind("add_shipping_info.ga4", function(data){
                    if(data.shipping_info && data.shipping_info.selected){
                        const items = data.items.map(function(item){
                            return{
                                "item_id": item.sku,
                                "item_name": item.sku_name,
                                "quantity": item.quantity
                            }
                        });
                        dataLayer.push({ items: null, value: null });
                        dataLayer.push({
                            event: "add_shipping_info",
                            shipping_tier: data.shipping_info.selected.shipping_name,
                            items: items
                        });
                    };
                });

                window.cvz.events.bind("add_payment_info.ga4", function(data){
                    if(data.payment_selected){
                        const items = data.items.map(function(item){
                            return {
                                "item_id": item.sku,
                                "item_name": item.sku_name,
                                "quantity": item.quantity
                            }
                        });
                        dataLayer.push({ items: null, value: null });
                        dataLayer.push({
                            event: "add_payment_info",
                            payment_type: data.payment_selected.group,
                            items: items
                        });
                    };
                });

                window.cvz.events.bind("purchase.ga4", function(data){
                    data.event = "purchase";
                    dataLayer.push({ items: null, value: null });
                    dataLayer.push(data);
                });

                
            }
        })();
